function isHappy(n: number): boolean {
  // Сумма квадратов цифр числа
  const next = (x: number): number => {
    let sum = 0;
    while (x > 0) {
      const d = x % 10;
      sum += d * d;
      x = Math.floor(x / 10);
    }
    return sum;
  };

  // Уже встреченные числа — чтобы заметить цикл
  const seen = new Set<number>();

  while (n !== 1) {
    // Число повторилось — мы в цикле без единицы
    if (seen.has(n)) return false;
    seen.add(n);
    n = next(n);
  }

  // Дошли до 1 — число счастливое
  return true;
}

// Время: O(log n) — после первого шага числа быстро становятся малыми
// Память: O(log n) — размер множества
